import math
import random
from pydantic import BaseModel
from typing import List, Optional, Dict, Any, Tuple, Set
from enum import Enum
from abc import abstractmethod

# Assume BaseStrategy, StrategyType, BaseMessageDataType, Info are defined
# Example definitions based on the template context:
class BaseStrategy(BaseModel):
    name: str
    history: List = []
    # Add any other fields your specific BaseStrategy might have

class StrategyType(Enum):
    Custom = "Custom"
    # Add other strategy types if they exist

class BaseMessageDataType(BaseModel):
    data: Any
    type: str

class Info(BaseModel):
    sender: str
    receiver: str
    difficulty: Optional[Any] = None
    message: List[BaseMessageDataType]


class SudoKillCustomStrategy:
    def __init__(self, model: BaseStrategy):
        self._model = model
        self.name = self._model.name
        self.history = self._model.history
        self.strategy_type = StrategyType.Custom
        self.N = 0
        self.sqrt_N = 0

    def _get_possible_numbers(self, grid: List[List[int]], r: int, c: int) -> Set[int]:
        """Returns the set of numbers (1-N) that can legally be placed at (r, c)."""
        # Assumes self.N and self.sqrt_N are already set
        if grid[r][c] != 0:
            return set()

        possible = set(range(1, self.N + 1))

        # Remove numbers in row
        possible -= {val for val in grid[r] if val != 0}

        # Remove numbers in column
        possible -= {grid[i][c] for i in range(self.N) if grid[i][c] != 0}

        # Remove numbers in subgrid
        start_row, start_col = r - r % self.sqrt_N, c - c % self.sqrt_N
        for i in range(self.sqrt_N):
            for j in range(self.sqrt_N):
                 if grid[start_row + i][start_col + j] != 0:
                    possible.discard(grid[start_row + i][start_col + j])

        return possible

    def _get_valid_moves(self, grid: List[List[int]], prev_move: Optional[List]) -> List[List[Any]]:
        """Calculates all valid moves [[(r, c), num], ...] for the current player."""
        # Assumes self.N and self.sqrt_N are already set
        if self.N == 0: return []

        valid_moves = []
        candidate_cells = []
        constrained_search = False # Flag to track if we are searching under row/col constraint

        if prev_move is None:
            # First move: any empty cell
            for r in range(self.N):
                for c in range(self.N):
                    if grid[r][c] == 0:
                        candidate_cells.append((r, c))
        else:
            # Subsequent moves: constrained to row/column
            constrained_search = True
            prev_r, prev_c = prev_move[0]
            added_cells = set() # To avoid duplicates

            # Check row prev_r
            for c in range(self.N):
                if grid[prev_r][c] == 0:
                    if (prev_r, c) not in added_cells:
                         candidate_cells.append((prev_r, c))
                         added_cells.add((prev_r, c))
            # Check column prev_c
            for r in range(self.N):
                if grid[r][prev_c] == 0:
                     if (r, prev_c) not in added_cells:
                         candidate_cells.append((r, prev_c))
                         added_cells.add((r, prev_c))

        # Find valid numbers for candidate cells
        constrained_moves_found = False
        for r, c in candidate_cells:
            possible_nums = self._get_possible_numbers(grid, r, c)
            for num in possible_nums:
                 # We don't need _is_valid here as _get_possible_numbers handles Sudoku rules
                 valid_moves.append([(r, c), num])
                 constrained_moves_found = True

        # Handle "move anywhere" fallback if constrained search yielded no moves
        if constrained_search and not constrained_moves_found:
            valid_moves = [] # Reset moves, start fallback search
            candidate_cells_fallback = []
            for r in range(self.N):
                for c in range(self.N):
                    if grid[r][c] == 0:
                        candidate_cells_fallback.append((r, c))

            for r, c in candidate_cells_fallback:
                 possible_nums = self._get_possible_numbers(grid, r, c)
                 for num in possible_nums:
                    valid_moves.append([(r, c), num])

        return valid_moves

    def receive_message(self, message: Info) -> Info:
        grid: List[List[int]] = message.message[0].data[1]
        prev_move: Optional[List] = message.message[0].data[0]

        self.N = len(grid)
        if self.N > 0:
             # Ensure N is a perfect square as per rules
             sqrt_N_float = math.sqrt(self.N)
             if sqrt_N_float != int(sqrt_N_float):
                 print(f"ERROR: Grid size N={self.N} is not a perfect square.")
                 # Handle error: return no move or raise exception
                 return Info(sender=self.__class__.__name__, receiver=message.sender, difficulty=message.difficulty, message=[BaseMessageDataType(data=None, type='custom')])
             self.sqrt_N = int(sqrt_N_float)
        else:
             # Handle empty grid case - return no move
             print("ERROR: Received empty grid.")
             return Info(
                sender=self.__class__.__name__,
                receiver=message.sender,
                difficulty=message.difficulty,
                message=[BaseMessageDataType(data=None, type='custom')]
            )

        # 1. Get all valid moves for the current player
        my_valid_moves = self._get_valid_moves(grid, prev_move)

        chosen_move = None

        if not my_valid_moves:
            # If no valid moves, we lose. Return None as move data.
            print(f"WARNING: Player {self.name} has no valid moves!") # Log for debugging
            chosen_move = None
        else:
            best_move = None
            min_score = float('inf')
            winning_move = None

            # 2. Evaluate each potential move
            for move in my_valid_moves:
                (r, c), num = move

                # Simulate the move
                temp_grid = [row[:] for row in grid] # Deep copy
                temp_grid[r][c] = num

                # --- Check if this move is a winning move --- 
                # Calculate opponent's moves AFTER we make 'move'
                # Opponent's prev_move will be our current 'move'
                opponent_moves_post_move = self._get_valid_moves(temp_grid, move)
                num_opponent_moves = len(opponent_moves_post_move)

                if num_opponent_moves == 0:
                     winning_move = move
                     # Found an immediate winning move, no need to check others
                     break

                # --- Heuristic Score Calculation (if not immediate win) ---
                current_score = num_opponent_moves

                # Check if this move forces opponent into a "free move"
                # This happens if opponent has > 0 total moves, but 0 constrained moves.
                opponent_can_move_constrained = False
                if num_opponent_moves > 0:
                    # Check if any constrained moves exist for the opponent
                    # Opponent is constrained by row 'r' and column 'c' of our move
                    opponent_candidate_cells_constrained = set()
                    # Row r (where we just moved)
                    for opp_c in range(self.N):
                        if temp_grid[r][opp_c] == 0: opponent_candidate_cells_constrained.add((r, opp_c))
                    # Column c (where we just moved)
                    for opp_r in range(self.N):
                        # Add cell only if it wasn't already added from the row check
                        if temp_grid[opp_r][c] == 0: opponent_candidate_cells_constrained.add((opp_r, c))

                    for opp_r_check, opp_c_check in opponent_candidate_cells_constrained:
                         # Check if there's any valid number for this constrained cell
                         if self._get_possible_numbers(temp_grid, opp_r_check, opp_c_check):
                              opponent_can_move_constrained = True
                              break

                # Apply penalty if a non-winning move forces a free move
                if not opponent_can_move_constrained and num_opponent_moves > 0:
                     # Add penalty (e.g., N) for forcing a free move
                     current_score += self.N 

                # Update best move based on score
                if current_score < min_score:
                    min_score = current_score
                    best_move = move
                # Simple tie-breaking: keep the first best move found

            # 3. Select the final move
            if winning_move:
                chosen_move = winning_move
            elif best_move:
                chosen_move = best_move
            elif my_valid_moves: # Should have found a best_move if valid moves exist
                 # This case indicates an issue or all moves had infinite score (unlikely)
                 print(f"WARNING: Heuristic failed to select a best move. Falling back to first valid move: {my_valid_moves[0]}")
                 chosen_move = my_valid_moves[0] # Fallback to first valid move
            # If chosen_move is still None, it implies my_valid_moves was empty initially.

        # 4. Return the decision in the specified format
        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=chosen_move, type='custom')]
        )

    def update_model_field(self, field_name: str, value: Any):
        """Updates a field in the underlying model."""
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)
        else:
            # Optionally handle error or log if field doesn't exist
            print(f"Warning: Field '{field_name}' not found in model {self._model}")

import math
import copy
import random
from pydantic import BaseModel
from typing import List, Optional, Dict, Any, Tuple, Set
from enum import Enum
from abc import abstractmethod

from system.message import Info
from system.message import BaseMessageDataType
from model.strategy_type import StrategyType
from model.base import BaseStrategy


class SudoKillCustomStrategy:
    def __init__(self, model: BaseStrategy):
        self._model = model
        self.name = self._model.name
        self.history = self._model.history
        self.strategy_type = StrategyType.Custom
        self._N = None
        self._sqrt_N = None

    def _initialize_grid_params(self, grid: List[List[int]]):
        """Sets the grid size N and subgrid size sqrt_N."""
        if self._N is None:
            self._N = len(grid)
            if self._N == 0:
                raise ValueError("Received an empty grid.")
            sqrt_n_float = math.sqrt(self._N)
            self._sqrt_N = int(sqrt_n_float)
            if self._sqrt_N * self._sqrt_N != self._N:
                raise ValueError(f"Grid size {self._N} must be a perfect square.")

    def _get_possible_numbers(self, grid: List[List[int]], r: int, c: int) -> Set[int]:
        """Returns the set of numbers (1 to N) that can be legally placed at (r, c) according to Sudoku rules."""
        if r < 0 or r >= self._N or c < 0 or c >= self._N or grid[r][c] != 0:
            return set()

        possible = set(range(1, self._N + 1))

        # Check row
        possible -= set(num for num in grid[r] if num != 0)

        # Check column
        possible -= set(grid[i][c] for i in range(self._N) if grid[i][c] != 0)

        # Check subgrid
        start_row = self._sqrt_N * (r // self._sqrt_N)
        start_col = self._sqrt_N * (c // self._sqrt_N)
        for i in range(start_row, start_row + self._sqrt_N):
            for j in range(start_col, start_col + self._sqrt_N):
                if grid[i][j] != 0:
                    possible -= {grid[i][j]}

        return possible

    def _get_candidate_cells(self, grid: List[List[int]], prev_move: Optional[List[Any]]) -> List[Tuple[int, int]]:
        """Determines the list of valid (row, col) cells where the current player can move."""
        candidate_cells_set = set()
        forced_move = True # Assume we are forced to move in row/col initially

        if prev_move:
            prev_r, prev_c = prev_move[0]
            possible_rc_cells_found = False # Flag to check if any valid cell was found in row/col

            # Check row prev_r for valid empty cells
            for c in range(self._N):
                if grid[prev_r][c] == 0:
                    if self._get_possible_numbers(grid, prev_r, c):
                        candidate_cells_set.add((prev_r, c))
                        possible_rc_cells_found = True

            # Check col prev_c for valid empty cells
            for r in range(self._N):
                if grid[r][prev_c] == 0:
                    if self._get_possible_numbers(grid, r, prev_c):
                         # Set automatically handles duplicates
                         candidate_cells_set.add((r, prev_c))
                         possible_rc_cells_found = True

            if not possible_rc_cells_found:
                # Rule 6: No valid empty cells in the required row/column
                forced_move = False
        else:
            # Rule 4: First player may move anywhere
            forced_move = False

        if not forced_move:
            # Rule 6 / Rule 4: Can move anywhere - find all valid empty cells
            candidate_cells_set = set()
            for r in range(self._N):
                for c in range(self._N):
                    if grid[r][c] == 0:
                        if self._get_possible_numbers(grid, r, c):
                            candidate_cells_set.add((r, c))

        return list(candidate_cells_set)

    def _make_move(self, grid: List[List[int]], move: List[Any]) -> Optional[List[List[int]]]:
        """Creates a new grid state after applying the move."""
        new_grid = copy.deepcopy(grid)
        (r, c), val = move
        if 0 <= r < self._N and 0 <= c < self._N and new_grid[r][c] == 0:
            new_grid[r][c] = val
            return new_grid
        else:
            # This should not happen if called with a valid move generated from possible moves
            print(f"Error: Attempted invalid simulation move {move} on cell ({r},{c}) with value {grid[r][c]}")
            return None

    def _check_opponent_has_moves(self, grid: List[List[int]], last_move: List[Any]) -> bool:
        """Checks if the opponent has at least one valid move available after last_move."""
        opponent_candidate_cells = self._get_candidate_cells(grid, last_move)
        for r_opp, c_opp in opponent_candidate_cells:
             # Check if *any* number can be placed in this candidate cell
             if self._get_possible_numbers(grid, r_opp, c_opp):
                 return True # Found at least one valid move for the opponent
        return False # Opponent has no valid moves

    def _count_opponent_moves(self, grid: List[List[int]], last_move: List[Any]) -> int:
        """Counts the total number of valid (cell, number) moves the opponent has."""
        count = 0
        opponent_candidate_cells = self._get_candidate_cells(grid, last_move)
        for r_opp, c_opp in opponent_candidate_cells:
             possible_nums = self._get_possible_numbers(grid, r_opp, c_opp)
             count += len(possible_nums)
        return count

    def update_model_field(self, field_name: str, value: Any):
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    def receive_message(self, message: Info) -> Info:
        grid = message.message[0].data[1]
        prev_move = message.message[0].data[0]

        try:
            self._initialize_grid_params(grid)
        except ValueError as e:
            print(f"Error initializing grid parameters: {e}")
            # Return a default/dummy move if initialization fails
            return Info(
                sender=self.__class__.__name__,
                receiver=message.sender,
                difficulty=message.difficulty,
                message=[BaseMessageDataType(data=[(0, 0), 1], type='custom')] # Dummy move
            )

        # 1. Determine candidate cells
        candidate_cells = self._get_candidate_cells(grid, prev_move)

        # 2. Generate all potential valid moves [(row, col), number]
        potential_moves = []
        for r, c in candidate_cells:
            possible_nums = self._get_possible_numbers(grid, r, c)
            for num in possible_nums:
                potential_moves.append([(r, c), num])

        # Handle case where we have no valid moves (loss condition)
        if not potential_moves:
            print("Strategy: No valid moves available. We lose.")
            # Find any empty cell to return a syntactically valid move, even though it's a loss.
            first_empty = None
            for r_idx in range(self._N):
                for c_idx in range(self._N):
                    if grid[r_idx][c_idx] == 0:
                        first_empty = (r_idx, c_idx)
                        break
                if first_empty: break
            # If grid is full, return [(0,0),1], otherwise return first empty cell with 1
            move = [first_empty, 1] if first_empty else [[0, 0], 1]
            return Info(
                sender=self.__class__.__name__,
                receiver=message.sender,
                difficulty=message.difficulty,
                message=[BaseMessageDataType(data=move, type='custom')]
            )

        winning_moves = []
        non_losing_moves_with_opp_options = [] # Store as (move, opp_options_count)

        # 3. Evaluate potential moves: Check for immediate wins or calculate heuristic value
        for move in potential_moves:
            temp_grid = self._make_move(grid, move)
            if temp_grid is None:
                print(f"Warning: Simulation failed for move {move}. Skipping.")
                continue # Skip if move simulation failed

            # Check if this move makes the opponent lose immediately
            opponent_has_moves = self._check_opponent_has_moves(temp_grid, move)

            if not opponent_has_moves:
                winning_moves.append(move)
            else:
                 # Calculate opponent options for heuristic sorting later
                 opp_options_count = self._count_opponent_moves(temp_grid, move)
                 non_losing_moves_with_opp_options.append((move, opp_options_count))

        # 4. Choose the best move based on evaluation
        best_move = None
        if winning_moves:
            # Prioritize winning moves
            best_move = winning_moves[0] # Pick the first winning move found
            # print(f"Strategy: Found winning move: {best_move}")
        elif non_losing_moves_with_opp_options:
            # No winning move, choose move that minimizes opponent's next options
            non_losing_moves_with_opp_options.sort(key=lambda x: x[1]) # Sort by opponent options count (ascending)
            best_move = non_losing_moves_with_opp_options[0][0]
            # print(f"Strategy: Found heuristic move: {best_move} (Opponent options: {non_losing_moves_with_opp_options[0][1]})")
        else:
            # Fallback: Should not happen if potential_moves was non-empty. Choose first potential move.
            print("Warning: No winning or non-losing moves categorized. Fallback to first potential move.")
            best_move = potential_moves[0]

        # 5. Return the chosen move
        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=best_move, type='custom')]
        )

