def get_valid_numbers_for_cell(grid, r, c, n, sqrt_n):
    """Calculates the set of valid Sudoku numbers (1-N) for cell (r, c)."""
    if grid[r][c] != 0:
        return set() # Cell is already filled

    valid_nums = set(range(1, n + 1))

    # Check row
    present_in_row = {val for val in grid[r] if val != 0}
    valid_nums -= present_in_row

    # Check column
    present_in_col = {grid[i][c] for i in range(n) if grid[i][c] != 0}
    valid_nums -= present_in_col

    # Check subgrid
    start_row, start_col = r - r % sqrt_n, c - c % sqrt_n
    for i in range(sqrt_n):
        for j in range(sqrt_n):
            val = grid[start_row + i][start_col + j]
            if val != 0:
                valid_nums.discard(val) # Use discard as it might already be removed

    return valid_nums

