                    opp_has_valid_restricted_move = True

            if opp_has_valid_restricted_move:
                 # Opponent is restricted, count moves in restricted zone
                 opponent_total_valid_moves = opp_valid_move_count_in_restriction
            else:
                # Opponent can move anywhere, count all valid moves on the board
                opponent_total_valid_moves = 0 # Recalculate for 'anywhere'
                for opp_r_any in range(n):
                    for opp_c_any in range(n):
                        if next_grid[opp_r_any][opp_c_any] == 0:
                             opp_valid_nums_any = self._get_valid_numbers_for_cell(next_grid, opp_r_any, opp_c_any, n, sqrt_n)
