                move = [(r, c), num] # Found winning move
                return Info(sender=self.__class__.__name__, receiver=message.sender, difficulty=message.difficulty, message=[BaseMessageDataType(data=move, type='custom')])

            # If not a winning move, check if it's better than the current best move
            current_cell_options = cell_initial_options.get((r, c), float('inf')) # Get initial options for tie-break

            if opponent_total_valid_moves < min_opponent_moves:
                # Found a move that leaves opponent with fewer options
