             if grid[row][c] == num:
                 return False
        # Check column
        for r in range(n):
            if grid[r][col] == num:
                return False
        # Check subgrid
        start_row, start_col = self._get_subgrid_indices(row, col, sqrt_n)
        for i in range(start_row, start_row + sqrt_n):
            for j in range(start_col, start_col + sqrt_n):
                if grid[i][j] == num:
                    return False
        return True

    def _get_possible_numbers(self, grid, row, col, n, sqrt_n):
        """Returns a set of numbers (1-N) that can legally be placed at (row, col)."""
        # Assumes cell grid[row][col] is 0 (empty)
        possible = set(range(1, n + 1))

        # Check row conflicts
        for c_check in range(n):
            if grid[row][c_check] != 0:
                possible.discard(grid[row][c_check])

        # Check column conflicts
        for r_check in range(n):
            if grid[r_check][col] != 0:
                possible.discard(grid[r_check][col])

