# Helper function moved outside the class for potential reuse or clarity
def _get_valid_moves_helper(grid, N, prev_move):
    """Calculates all valid moves based on game rules and Sudoku constraints."""
    if N == 0: # Handle empty grid case
        return []
    sqrt_N = int(math.sqrt(N))
    if sqrt_N * sqrt_N != N:
        raise ValueError("Grid size N must be a perfect square.")

    all_empty_cells = []
    for r in range(N):
        for c in range(N):
            if grid[r][c] == 0:
                all_empty_cells.append((r, c))

    potential_cells_rc = set()
    if prev_move is None:
        # Rule 4: First move, any empty cell
        potential_cells_rc = set(all_empty_cells)
    else:
        # Rule 5: Subsequent moves, must be in the same row or column
        pr, pc = prev_move[0]
        constrained_empty_cells = []
        for r, c in all_empty_cells:
            if r == pr or c == pc:
                constrained_empty_cells.append((r,c))

        if not constrained_empty_cells:
             # Rule 6: If no valid empty cells in row/col, move anywhere
             potential_cells_rc = set(all_empty_cells)
        else:
             potential_cells_rc = set(constrained_empty_cells)

    valid_moves = []
    for r, c in potential_cells_rc:
        # Find valid numbers for cell (r, c) according to Sudoku rules
        possible_nums = set(range(1, N + 1))

        # Check row
        row_nums = set(grid[r]) - {0}
        possible_nums -= row_nums

        # Check column
        col_nums = set(grid[i][c] for i in range(N)) - {0}
        possible_nums -= col_nums

        # Check subgrid
        start_row = r // sqrt_N * sqrt_N
        start_col = c // sqrt_N * sqrt_N
        subgrid_nums = set()
        for i in range(start_row, start_row + sqrt_N):
            for j in range(start_col, start_col + sqrt_N):
                subgrid_nums.add(grid[i][j])
        subgrid_nums -= {0}
        possible_nums -= subgrid_nums

        # Add valid moves [(r, c), num] for this cell
        for num in possible_nums:
             valid_moves.append([(r, c), num])

    return valid_moves


